INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(44411, 'Ezekiel 16:25', 'Ezekiel', 16, 25, 'هو، تا د هرې کوڅې په سر کې د بدلمنتوب دپاره ځایونه جوړ کړل او خپل ښایست دې د کرکې وړ کړ او هرڅوک چې به تېرېده تا به ورسره زنا کوله او ستا زناکاري ورځ په ورځ زیاتېدله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_25.mp3', '', 1761754199, 1761754199),
(44412, 'Ezekiel 16:26', 'Ezekiel', 16, 26, 'ته د خپلو شهوت‌پرسته ګاونډیانو یعنې مصریانو سره څملاستلې او په خپلې زیاتېدونکې زناکارۍ سره دې زه په قهر کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_26.mp3', '', 1761754199, 1761754199),
(44413, 'Ezekiel 16:27', 'Ezekiel', 16, 27, 'نو بیا مې خپل لاس پورته کړ چې سزا درته درکړم او ستا ځمکه مې کمه کړه. ته مې خپلو دښمنانو یعنې فلسطیني ښځو ته چې ستا د بد‌اخلاقۍ نه کرکه کوي، تسلیم کړې یې. ما هغوی پرېښودل څه چې زړه یې غواړي، درسره وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_27.mp3', '', 1761754199, 1761754199),
(44414, 'Ezekiel 16:28', 'Ezekiel', 16, 28, 'تا د آشوریانو سره زناکاري وکړه، ځکه چې ستا شوق نه پوره کېده او حتی له هغې وروسته هم ستا شوق پوره نه شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_28.mp3', '', 1761754199, 1761754199),
(44415, 'Ezekiel 16:29', 'Ezekiel', 16, 29, 'همدارنګه تا د بابلیانو سره چې د سوداګرانو قوم دی، خپل بدلمنتوب نور هم زیات کړ، خو هغوی هم ونه شو کولی چې ستا شويق پوره کړي.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_29.mp3', '', 1761754199, 1761754199),
(44416, 'Ezekiel 16:30', 'Ezekiel', 16, 30, 'څښتن تعالی داسې وایي: ‹زه دې ډېر په قهر کړم، ځکه چې تا د یوې بې‌شرمې بدلمنې په شان دا ټول کارونه وکړل او دا دې وښودل چې هرڅه چې دې زړه وغواړي هغه کوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_30.mp3', '', 1761754199, 1761754199),
(44417, 'Ezekiel 16:31', 'Ezekiel', 16, 31, 'تا د هرې کوڅې په سر کې د بتانو د عبادت ځایونه او په هر چوک کې دې د بدلمنتوب دپاره ځایونه جوړ کړل. خو تا دا کار د نورو بدلمنو ښځو په شان د پیسو په خاطر نه کاوه او پیسې دې ردولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_31.mp3', '', 1761754199, 1761754199),
(44418, 'Ezekiel 16:32', 'Ezekiel', 16, 32, 'ته د هغې ښځې په شان یې چې د دې په ځای چې د خپل مېړه سره مینه وکړې، د پردیو خلکو سره زنا کوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_32.mp3', '', 1761754199, 1761754199),
(44419, 'Ezekiel 16:33', 'Ezekiel', 16, 33, 'خلک نورو بدلمنو ښځو ته سوغاتونه ورکوي، خو تا خپلو ټولو عاشقانو ته سوغاتونه او رشوتونه ورکول چې د هرځای نه راشي او تا سره څملي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_33.mp3', '', 1761754199, 1761754199),
(44420, 'Ezekiel 16:34', 'Ezekiel', 16, 34, 'نو ته د نورو بدلمنو ښځو په شان نه یې. ته دې کار ته چا نه هڅولې. تا به پیسې نه اخیستلې، بلکې هغو خلکو ته به دې ورکولې چې تا سره زنا وکړي! هو، ته د نورو په شان نه یې.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_34.mp3', '', 1761754199, 1761754199),
(44421, 'Ezekiel 16:35', 'Ezekiel', 16, 35, '«نو ای اورشلیمه، ای بدلمنې! څښتن چې څه وایي هغه ته غوږ ونیسه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_35.mp3', '', 1761754199, 1761754199),
(44422, 'Ezekiel 16:36', 'Ezekiel', 16, 36, 'دا هغه څه دي چې څښتن تعالی یې وایي: ‹تا خپل کالي وویستل او لکه د یوې بدلمنې په شان د خپلې شهوت پرستۍ په خاطر خپلو عاشقانو او د کرکې وړ بتانو دپاره تیاره وې او د خپلو اولادونو وینه دې بتانو ته د قربانۍ په توګه وړاندې کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_36.mp3', '', 1761754199, 1761754199),
(44423, 'Ezekiel 16:37', 'Ezekiel', 16, 37, 'نو له دې امله زه به ستا ټول پخواني عاشقان چې تا ورڅخه خوند اخیسته، پرته له دې چې په تا ګران وو او یا دې د هغوی څخه کرکه کوله، هغوی ټول به ستا نه ګردچاپېره راټول کړم، بیا به ستا نه کالي وباسم او هغوی به په پوره توګه تا لوڅه وویني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_37.mp3', '', 1761754199, 1761754199),
(44424, 'Ezekiel 16:38', 'Ezekiel', 16, 38, 'زه به تا داسې محاکمه کړم لکه څنګه چې یوه زناکاره او قاتله ښځه محکمه کیږي او په خپل قهر او غیرت سره به درته د مرګ سزا درکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_38.mp3', '', 1761754199, 1761754199),
(44425, 'Ezekiel 16:39', 'Ezekiel', 16, 39, 'زه به تا خپلو عاشقانو ته په لاس ورکړم او هغوی به هغه ځایونه وران کړي چې تا په کې د بتانو عبادت او بدلمنتوب کاوه. هغوی به ستا نه کالي وباسي، ښایسته زېورات به ستا نه واخلي او تا به په پوره توګه لوڅه پرېږدي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_39.mp3', '', 1761754199, 1761754199),
(44426, 'Ezekiel 16:40', 'Ezekiel', 16, 40, 'ستا عاشقان به ډېر خلک راوپاروي چې تا سنګساره کړي او په خپلو تورو به دې ټوټې ټوټې کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_40.mp3', '', 1761754199, 1761754199),
(44427, 'Ezekiel 16:41', 'Ezekiel', 16, 41, 'هغوی به ستا کورونه وسوځوي او د ډېرو ښځو په مخکې به درته سزا درکړي. زه به تا دې ته مجبوره کړم چې بدلمنتوب پرېږدې او خپلو عاشقانو ته د سوغاتونو د ورکولو نه لاس واخلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_41.mp3', '', 1761754199, 1761754199),
(44428, 'Ezekiel 16:42', 'Ezekiel', 16, 42, 'بیا به زه ارام شم او زما د غیرت قهر به سوړ شي او زه به نور په تا باندې نه په قهرېږم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_42.mp3', '', 1761754199, 1761754199),
(44429, 'Ezekiel 16:43', 'Ezekiel', 16, 43, 'تا هېر کړي دي کله چې ځوانه وې، ما درباندې څومره پام کاوه، خو تا په خپلو ټولو بدو کارونو زه په قهر کړم. نو په دې خاطر زه تاته د دې ټولو بدو عملونو په بدل کې سزا درکوم. برسېره په هغو ټولو د کرکې وړ کارونو، زنا دې ولې کوله؟ څښتن تعالی داسې ویلي دي.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_43.mp3', '', 1761754199, 1761754199),
(44430, 'Ezekiel 16:44', 'Ezekiel', 16, 44, '«څښتن وویل: ‹ای اورشلیمه، هغه خلک چې متلونه خوښوي، نو هغوی به ستا په هکله دا متل وایي: ”څنګه یې چې مور وي، نو هماغسې به یې لور هم وي.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_44.mp3', '', 1761754199, 1761754199),
(44431, 'Ezekiel 16:45', 'Ezekiel', 16, 45, 'ته په رښتیا د خپلې مور په شان یې چې د خپل مېړه او خپلو اولادونو نه به یې کرکه کوله. ته هم د خپلو خویندو په شان یې چې د خپلو مېړونو او خپلو اولادونو نه به یې کرکه کوله. ستا مور حیتۍ وه او ستا پلار اموري ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_45.mp3', '', 1761754199, 1761754199),
(44432, 'Ezekiel 16:46', 'Ezekiel', 16, 46, 'ستا مشره خور سامره ده چې د خپلو لورګانو سره ستا په شمال کې اوسیږي. ستا کشره خور سدوم ده چې د خپلو لورګانو سره په جنوب کې اوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_46.mp3', '', 1761754199, 1761754199),
(44433, 'Ezekiel 16:47', 'Ezekiel', 16, 47, 'ته نه یوازې دا چې د هغوی په لارو باندې روانه شوې او د هغوی د کرکې وړ کارونو پیروي دې وکړه، بلکې په ډېر لږ وخت کې دې د هغوی نه هم زیات د فساد نه ډک کارونه وکړل.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_47.mp3', '', 1761754199, 1761754199),
(44434, 'Ezekiel 16:48', 'Ezekiel', 16, 48, 'څښتن تعالی داسې وایي: ‹زه په خپل ذات باندې قسم خورم چې ستا خور سدوم او د هغې لورګانو هېڅکله داسې بد کارونه نه دي کړي لکه څنګه چې تا او ستا لورګانو کړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_48.mp3', '', 1761754199, 1761754199),
(44435, 'Ezekiel 16:49', 'Ezekiel', 16, 49, 'ګوره، سدوم او د هغې لورګانې مغروره وې، د خوراک دپاره یې هرڅه پرېمانه درلودل او په سوله او ارامۍ کې یې ژوند کاوه. خو د هغوی ګناه دا وه چې د غریبو او حاجتمندو خلکو سره یې مرسته نه کوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_49.mp3', '', 1761754199, 1761754199),
(44436, 'Ezekiel 16:50', 'Ezekiel', 16, 50, 'هغوی مغرور خلک وو او هغه کارونه یې کول چې ما ورڅخه کرکه کوله. نو کله چې ما دا ولیدل، هغوی مې له منځه یووړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_50.mp3', '', 1761754199, 1761754199),
(44437, 'Ezekiel 16:51', 'Ezekiel', 16, 51, 'سامرې ستا په نیمه اندازه ګناه هم نه ده کړې. تا دومره بد کارونه وکړل چې هغې کله هم نه دي کړي. تا دومره د کرکې وړ کارونه کړي دي چې د هغو کارونو په پرتله ستا خویندې بې‌ګناه ښکاري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_51.mp3', '', 1761754199, 1761754199),
(44438, 'Ezekiel 16:52', 'Ezekiel', 16, 52, 'نو ته به اوس خپله رسوایي وزغمې. ستا ګناهونه ستا د خویندو نه دومره زیات دي چې ته د دې سبب شوې چې هغوی ستا په پرتله بې‌ګناه ښکاره شي. نو اوس وشرمېږه او خپله بې‌عزتي وزغمه، ځکه چې تا دومره د کرکې وړ کارونه کړي دي چې ستا خویندې پاکې ښکاره شي.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_52.mp3', '', 1761754199, 1761754199),
(44439, 'Ezekiel 16:53', 'Ezekiel', 16, 53, '«څښتن اورشلیم ته وویل: ‹زه به سدوم او د هغې لورګانې او سامره او د هغې لورګانې یوځل بیا نېکمرغه کړم. هو، تا به هم اباد کړم،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_53.mp3', '', 1761754199, 1761754199),
(44440, 'Ezekiel 16:54', 'Ezekiel', 16, 54, 'ترڅو ته د هغو کارونو په خاطر چې کړي دې دي، وشرمېږې او ستا خویندې به خوشحاله شي چې هغوی ستا په شان ګناهکارې نه دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_54.mp3', '', 1761754199, 1761754199),
(44441, 'Ezekiel 16:55', 'Ezekiel', 16, 55, 'ستا خویندې سدوم او سامره او د هغوی لورګانې به بېرته خپل پخواني حالت ته راشي او ته او ستا لورګانې به هم بېرته خپل پخواني حال ته راشئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_55.mp3', '', 1761754199, 1761754199),
(44442, 'Ezekiel 16:58', 'Ezekiel', 16, 58, 'ته باید د خپلې شهوت پرستۍ او د کرکې وړ کارونو په خاطر چې کړي دې دي، سزا ووینې.› څښتن داسې ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_58.mp3', '', 1761754199, 1761754199),
(44443, 'Ezekiel 16:59', 'Ezekiel', 16, 59, 'څښتن تعالی داسې وایي: ‹زه به ستا سره داسې چلند وکړم چې څنګه یې لایقه یې، ځکه چې تا خپله وعده هېره کړې ده او خپل لوظ دې مات کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_59.mp3', '', 1761754199, 1761754199),
(44444, 'Ezekiel 16:60', 'Ezekiel', 16, 60, 'خو زه به خپل هغه لوظ رایاد کړم چې ستا سره مې ستا د ځوانۍ په وخت کې کړی ؤ او ستا سره به یو ابدي لوظ وکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_60.mp3', '', 1761754199, 1761754199),
(44445, 'Ezekiel 16:61', 'Ezekiel', 16, 61, 'هغه وخت به دې بد کارونه در په یاد شي، کله چې زه تاته خپله مشره او کشره خور بېرته راولم، نو ته به وشرمېږې. زه به هغوی ستا لورګانې کړم، که څه هم دا خبره په هغه لوظ کې نشته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_61.mp3', '', 1761754199, 1761754199),
(44446, 'Ezekiel 16:62', 'Ezekiel', 16, 62, 'زه به ستا سره خپل لوظ ټینګ وساتم، نو هغه وخت به ته پوهه شې چې زه څښتن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_62.mp3', '', 1761754199, 1761754199),
(44447, 'Ezekiel 16:63', 'Ezekiel', 16, 63, 'زه به ستا د ټولو ګناهونو دپاره کفاره ادا کړم، خو ته به د هغو په رایادولو د ډېره شرمه خپله خوله خلاصولی نه شې.› څښتن تعالی داسې ویلي دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_63.mp3', '', 1761754199, 1761754199),
(44448, 'Numbers 1:1', 'Numbers', 1, 1, 'د مصر څخه د اسراییلو د قوم د راوتلو څخه وروسته د دوهم کال د دوهمې میاشتې په لومړۍ ورځ کله چې څښتن د موسی سره د سینا په دښته کې په سپېڅلې خېمه کې خبرې وکړې، هغه وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers1_verse_1.mp3', '', 1761754199, 1761754199),
(44449, 'Numbers 1:2', 'Numbers', 1, 2, '«ته او هارون طایفه په طایفه او کورنۍ په کورنۍ د اسراییلو د ټول قوم سرشمېرنه وکړئ او د هغو ټولو خلکو د نومونو لست ولیکئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers1_verse_2.mp3', '', 1761754199, 1761754199),
(44450, 'Numbers 1:3', 'Numbers', 1, 3, 'چې عمر یې شل کاله یا زیات وي او جنګ کولای شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers1_verse_3.mp3', '', 1761754199, 1761754199),
(44451, 'Numbers 1:4', 'Numbers', 1, 4, 'د هرې قبیلې د طایفې د یو مشر څخه مرسته وغواړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers1_verse_4.mp3', '', 1761754199, 1761754199),
(44452, 'Numbers 1:5', 'Numbers', 1, 5, 'دا د هغو مشرانو نومونه دي چې تاسو سره باید مرسته وکړي: د روبین د قبیلې څخه الیصور د شدییور زوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers1_verse_5.mp3', '', 1761754199, 1761754199),
(44453, 'Numbers 1:6', 'Numbers', 1, 6, 'د شمعون د قبیلې څخه شلومی ییل د صوریشدای زوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers1_verse_6.mp3', '', 1761754199, 1761754199),
