(44462, 'Numbers 1:15', 'Numbers', 1, 15, 'د نفتالي د قبیلې څخه اخیرع د عینان زوی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers1_verse_15.mp3', '', 1761754199, 1761754199),
(44463, 'Numbers 1:16', 'Numbers', 1, 16, 'دا خلک قبیلوي مشران وو چې د اسراییلو د قوم څخه د دې کار دپاره وټاکل شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers1_verse_16.mp3', '', 1761754199, 1761754199),
(44464, 'Numbers 1:17', 'Numbers', 1, 17, 'د دې دولسو کسانو په مرسته موسی او هارون', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers1_verse_17.mp3', '', 1761754199, 1761754199),
(44465, 'Numbers 1:18', 'Numbers', 1, 18, 'د دوهمې میاشتې په لومړۍ ورځ ټول قوم راوغوښت. خلکو خپل نومونه طایفه په طایفه او کورنۍ په کورنۍ ولیکل او هغه کسان چې عمر یې شل کاله یا زیات ؤ د هر یو نوم په لست کې ولیکل شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers1_verse_18.mp3', '', 1761754199, 1761754199),
(44466, 'Numbers 1:19', 'Numbers', 1, 19, 'څنګه چې څښتن موسی ته امر کړی ؤ، هغوی یې د سینا په دښته کې وشمېرل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers1_verse_19.mp3', '', 1761754199, 1761754199),
(44467, 'Numbers 1:47', 'Numbers', 1, 47, 'خو هغه خلک چې د لاوي د قبیلې څخه وو په دې کې شامل نه وو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers1_verse_47.mp3', '', 1761754199, 1761754199),
(44468, 'Numbers 1:48', 'Numbers', 1, 48, 'ځکه چې څښتن موسی ته ویلي وو:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers1_verse_48.mp3', '', 1761754199, 1761754199),
(44469, 'Numbers 1:49', 'Numbers', 1, 49, '«کله چې ته د هغو کسانو سرشمېرنه کوې چې جنګ کولای شي، نو د لاوي قبیله په کې مه شاملوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers1_verse_49.mp3', '', 1761754199, 1761754199),
(44470, 'Numbers 1:50', 'Numbers', 1, 50, 'د هغې په ځای لاویان د سپېڅلې خېمې او د هغې د ټول سامان مسوولان وټاکه. هغوی به دا خېمه او د هغې سامان وړي، ساتنه به یې کوي او د هغې په شاوخوا کې به خپلې خېمې ودروي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers1_verse_50.mp3', '', 1761754199, 1761754199),
(44471, 'Numbers 1:51', 'Numbers', 1, 51, 'هرکله چې تاسو خپلې خېمې بل ځای ته وړئ، نو لاویان دې سپېڅلې خېمه راټوله کړي او په نوي ځای کې دې بیا ودروي. که بل هرڅوک ورته نژدې ورشي وبه وژل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers1_verse_51.mp3', '', 1761754199, 1761754199),
(44472, 'Numbers 1:52', 'Numbers', 1, 52, 'پاتې اسراییلیان به د خپلو ډلو له مخې خېمې ودروي، هر سړی به د خپل بیرغ لاندې د خپلې ډلې سره وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers1_verse_52.mp3', '', 1761754199, 1761754199),
(44473, 'Numbers 1:53', 'Numbers', 1, 53, 'خو لاویان به خپلې خېمې د سپېڅلې خېمې په شاوخوا کې ودروي، ترڅو د اسراییلو په قوم باندې زما قهر نازل نه شي. لاویان دې د سپېڅلې خېمې د ساتلو مسوولیت په غاړه واخلي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers1_verse_53.mp3', '', 1761754199, 1761754199),
(44474, 'Numbers 1:54', 'Numbers', 1, 54, 'څنګه چې څښتن موسی ته امر کړی ؤ، اسراییلیانو کټ مټ هماغسې وکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers1_verse_54.mp3', '', 1761754199, 1761754199),
(44475, 'Genesis 8:1', 'Genesis', 8, 1, 'خدای نوح او هغه ټول حیوانات چې په کشتۍ کې د هغه سره وو را په یاد کړل، نو خدای په ځمکه باندې باد راوالوزاوه او اوبه په کمېدلو شوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis8_verse_1.mp3', '', 1761754199, 1761754199),
(44476, 'Genesis 8:2', 'Genesis', 8, 2, 'خدای د ځمکې لاندې اوبه او د اسمان د اوبو دروازې بندې کړې او باران ودرېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis8_verse_2.mp3', '', 1761754199, 1761754199),
(44477, 'Genesis 8:3', 'Genesis', 8, 3, 'په یوسلو پنځوسو ورځو کې اوبه ورو، ورو د ځمکې د مخ څخه کمې شوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis8_verse_3.mp3', '', 1761754199, 1761754199),
(44478, 'Genesis 8:4', 'Genesis', 8, 4, 'او د اوومې میاشتې په اوولسمه ورځ کشتۍ د ارارات په غرونو باندې ودرېدله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis8_verse_4.mp3', '', 1761754199, 1761754199),
(44479, 'Genesis 8:5', 'Genesis', 8, 5, 'اوبه کمې شوې او د لسمې میاشتې په لومړۍ ورځ د غرونو څوکې ښکاره شوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis8_verse_5.mp3', '', 1761754199, 1761754199),
(44480, 'Genesis 8:6', 'Genesis', 8, 6, 'وروسته له څلوېښتو ورځو نوح د کشتۍ کړکۍ خلاصه کړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis8_verse_6.mp3', '', 1761754199, 1761754199),
(44481, 'Genesis 8:7', 'Genesis', 8, 7, 'او یو کارغه یې دباندې ولېږه، خو کارغه به یو خوا او بل خواته الوت، تر هغې پورې چې ځمکه وچه شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis8_verse_7.mp3', '', 1761754199, 1761754199),
(44482, 'Genesis 8:8', 'Genesis', 8, 8, 'نوح غوښتل پوه شي چې ایا د ځمکې په مخ باندې اوبه کمې شوې دي یا نه، نو یوه کوتره یې والوزوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis8_verse_8.mp3', '', 1761754199, 1761754199),
(44483, 'Genesis 8:9', 'Genesis', 8, 9, 'خو کوترې د خپل ځان دپاره د ناستې ځای پیدا نه کړ ځکه چې د ځمکې په مخ باندې لا اوبه ولاړې وې او هغه بېرته کشتۍ ته راستنه شوه. نوح خپل لاس وراوږد کړ، هغه یې ونیوله او کشتۍ ته یې ننه‌ایستله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis8_verse_9.mp3', '', 1761754199, 1761754199),
(44484, 'Genesis 8:10', 'Genesis', 8, 10, 'هغه اووه ورځې نور صبر وکړ او بیا یې کوتره ولېږله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis8_verse_10.mp3', '', 1761754199, 1761754199),
(44485, 'Genesis 8:11', 'Genesis', 8, 11, 'کوتره د ماښام په وخت کې بېرته هغه ته راستنه شوه او د زیتون تازه پاڼه یې په مښوکه کې نیولې وه، نو نوح پوه شو چې اوبه کمې شوې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis8_verse_11.mp3', '', 1761754199, 1761754199),
(44486, 'Genesis 8:12', 'Genesis', 8, 12, 'هغه اووه ورځې نور انتظار وکړ او یوځل بیا یې کوتره ولېږله، خو دا ځل هغه بېرته رانغله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis8_verse_12.mp3', '', 1761754199, 1761754199),
(44487, 'Genesis 8:13', 'Genesis', 8, 13, 'په هغه وخت کې نوح د شپږ سوه یو کالو په عمر ؤ. د هماغه کال د اولې میاشتې په لومړۍ نېټه ځمکه مخ په وچېدلو شوه. نوح د کشتۍ پوښ لېرې کړ، شاوخوا یې وکتل او ویې لیدل چې د ځمکې مخ وچ شوی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis8_verse_13.mp3', '', 1761754199, 1761754199),
(44488, 'Genesis 8:14', 'Genesis', 8, 14, 'د دوهمې میاشتې په اوویشتمه ورځ ځمکه بیخي وچه شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis8_verse_14.mp3', '', 1761754199, 1761754199),
(44489, 'Genesis 8:15', 'Genesis', 8, 15, 'خدای نوح ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis8_verse_15.mp3', '', 1761754199, 1761754199),
(44490, 'Genesis 8:16', 'Genesis', 8, 16, '«د خپلې ښځې، خپلو زامنو او د هغو د ښځو سره د کشتۍ څخه دباندې راووځئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis8_verse_16.mp3', '', 1761754199, 1761754199),
(44491, 'Genesis 8:17', 'Genesis', 8, 17, 'ټول مرغان او حیوانات د ځان سره دباندې راوباسه، ترڅو دوی خپل همجنس وزېږوي او په ټوله ځمکه باندې خپاره شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis8_verse_17.mp3', '', 1761754199, 1761754199),
(44492, 'Genesis 8:18', 'Genesis', 8, 18, 'نو نوح د خپلې ښځې، خپلو زامنو او د هغوی د ښځو سره د کشتۍ څخه راووت.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis8_verse_18.mp3', '', 1761754199, 1761754199),
(44493, 'Genesis 8:19', 'Genesis', 8, 19, 'ټول حیوانات او مرغان د خپلو جنسونو سره ډلې ډلې د کشتۍ څخه ووتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis8_verse_19.mp3', '', 1761754199, 1761754199),
(44494, 'Genesis 8:20', 'Genesis', 8, 20, 'نوح د څښتن دپاره د قربانۍ ځای جوړ کړ او هغه د هر ډول پاکو حیواناتو او مرغانو څخه یو یو واخیست او هغه ټول یې د قربانۍ په ځای کې د سوځېدونکې نذرانې په توګه قرباني کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis8_verse_20.mp3', '', 1761754199, 1761754199),
(44495, 'Genesis 8:21', 'Genesis', 8, 21, 'او د سوځېدونکې قربانۍ بوی په څښتن باندې ښه ولګېده، هغه د خپل ځان سره وویل: «زه به بیا هېڅکله ځمکه د انسان د عملونو په سبب لعنتي نه کړم. زه پوهېږم چې د انسان خیال د هغه د ځوانۍ له وخت څخه خراب دی، خو زه به هېڅکله بیا ټول ژوندي موجودات له منځه نه وړم لکه څنګه چې مې له منځه یووړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis8_verse_21.mp3', '', 1761754199, 1761754199),
(44496, 'Genesis 8:22', 'Genesis', 8, 22, 'ترڅو پورې چې دنیا موجوده وي، نو د ځمکې کرل او رېبل، یخني او ګرمي، اوړی او ژمی او شپه او ورځ به هم وي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis8_verse_22.mp3', '', 1761754199, 1761754199),
(44497, 'Ezekiel 21:1', 'Ezekiel', 21, 1, 'څښتن ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel21_verse_1.mp3', '', 1761754199, 1761754199),
(44498, 'Ezekiel 21:2', 'Ezekiel', 21, 2, '«ای فاني انسانه، خپل مخ د اورشلیم خواته واړوه. د عبادتځایونو په ضد خبرې وکړه. د اسراییلو د هېواد په ضد نبوت وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel21_verse_2.mp3', '', 1761754199, 1761754199),
(44499, 'Ezekiel 21:3', 'Ezekiel', 21, 3, 'زه څښتن تاسو ته داسې وایم: ‹ګورئ، زه ستاسو په ضد یم. زه به خپله توره د پوښ نه راوباسم او ټول نېک او بدکاره خلک به ووژنم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel21_verse_3.mp3', '', 1761754199, 1761754199),
(44500, 'Ezekiel 21:4', 'Ezekiel', 21, 4, 'ځکه چې زه ښه او بد خلک دواړه وژنم، زه به خپله توره د پوښ نه راوباسم او د جنوب نه تر شماله پورې به د هرچا په وړاندې ورڅخه کار واخلم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel21_verse_4.mp3', '', 1761754199, 1761754199),
(44501, 'Ezekiel 21:5', 'Ezekiel', 21, 5, 'بیا به ټول خلک پوه شي چې ما څښتن خپله توره د پوښ نه راویستلې ده او هغه به بیا په پوښ کې نه ږدم.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel21_verse_5.mp3', '', 1761754199, 1761754199),
(44502, 'Ezekiel 21:6', 'Ezekiel', 21, 6, 'ای فاني انسانه، په مات زړه او ناامیدۍ سره زګېروی وکړه. د خلکو په مخکې له غمه فریادونه وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel21_verse_6.mp3', '', 1761754199, 1761754199),
(44503, 'Ezekiel 21:7', 'Ezekiel', 21, 7, 'کله چې درڅخه پوښتنه وکړي چې ولې زګېروی کوې، نو هغوی ته ووایه: ‹زه ځکه زګېروي کوم چې بد خبرونه مې اورېدلي دي. کله چې هغه رښتیا شي، نو د هغوی په زړونو کې به سخته وېره راپیدا شي، لاسونه به یې سست شي، روحیه به یې کمزورې شي او زنګنونه به یې ورپیږي. ګورئ، هغه وخت راتلونکی دی او هغه به عملي کیږي. څښتن تعالی داسې ویلي دي.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel21_verse_7.mp3', '', 1761754199, 1761754199),
(44504, 'Ezekiel 21:8', 'Ezekiel', 21, 8, 'څښتن ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel21_verse_8.mp3', '', 1761754199, 1761754199),
(44505, 'Ezekiel 21:9', 'Ezekiel', 21, 9, '«ای فاني انسانه، نبوت وکړه. خلکو ته ووایه چې زه څښتن داسې وایم: ‹ما تېره کړې خپله توره او صیقل شوې هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel21_verse_9.mp3', '', 1761754199, 1761754199),
(44506, 'Ezekiel 21:10', 'Ezekiel', 21, 10, 'د وژلو په خاطر ده تېره شوې هغه ده صیقل شوې چې وځلیږي لکه برېښنا په شان خوشحالي به نه وي ځکه چې قوم نه ده ساتلې پروا زما د هر خبرداري او سزا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel21_verse_10.mp3', '', 1761754199, 1761754199),
(44507, 'Ezekiel 21:11', 'Ezekiel', 21, 11, 'نو ما یو چاته توره ورکړه چې صیقل کړي هغه چې ترې واخیستل شي کار ده تېره شوې او صیقل شوې هغه چې یو وژونکي ته په لاس ورکړل شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel21_verse_11.mp3', '', 1761754199, 1761754199),
(44508, 'Ezekiel 21:12', 'Ezekiel', 21, 12, 'ای فاني انسانه، له غمه وکړه انګولا او ویر ځکه دا توره ویستل شوې زما د قوم په ضد او د اسراییلو د مشرانو په ضد هغوی به ووژل شي زما د پاتې ټولو خلکو سره د نا‌امیدۍ له لاسه ووهه خپل ځان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel21_verse_12.mp3', '', 1761754199, 1761754199),
(44509, 'Ezekiel 21:13', 'Ezekiel', 21, 13, 'ازمایل کیږي زما قوم که هغوی وکړي انکار له توبې ویستلو نو پېښ به شي دا هرڅه ورباندې څښتن تعالی داسې ویلي دي.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel21_verse_13.mp3', '', 1761754199, 1761754199),
(44510, 'Ezekiel 21:14', 'Ezekiel', 21, 14, 'نو ای فاني انسانه، نبوت وکړه. خپل لاسونه وپړکوه او دوه، درې ځلې په تورې باندې ګوزار وکړه. دا هغه توره ده چې ډېر خلک وژني، داسې توره ده چې له هرې خوا حمله کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel21_verse_14.mp3', '', 1761754199, 1761754199);